package com.hms.appointments;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/patients/{patientId}/communication-consent") public class PatientConsentController {private final TenantRepository tenants;private final PatientRepository patients;public PatientConsentController(TenantRepository t,PatientRepository p){tenants=t;patients=p;} @PutMapping public Patient update(@PathVariable String tenantSlug,@PathVariable UUID patientId,@Valid @RequestBody CommunicationConsentRequest request){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));Patient patient=patients.findById(patientId).filter(p->p.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Patient not found"));patient.updateCommunicationConsent(request);return patients.save(patient);}}
